css:
html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.cuatro-valores, .cuatro-valores * {
  box-sizing: border-box;
}

.cuatro-valores {
  display: grid;
  grid-template-rows: repeat(4, minmax(0, 1fr));
  width: 100%;
  height: 100%;
  padding: 0;
  margin: 0;
  border: 0;
  gap: 0;
  background: transparent !important;
  color: #223151;
  font-family: Consolas, "Lucida Console", "Courier New", monospace;
  font-variant-numeric: tabular-nums;
  opacity: var(--w-opacity, 1);
  pointer-events: none;
}

.valor-celda {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: transparent;
}

.valor-celda.is-writable {
  pointer-events: auto;
  cursor: text;
}

.valor-contenido {
  display: inline-block;
  flex: none;
  max-width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.15;
  text-align: center;
  white-space: nowrap;
  overflow: visible;
  /* Para ajustar manualmente: menor = arriba, mayor = abajo. */
  transform: translateY(0.05em);
}

.valor-celda.is-editing .valor-contenido {
  visibility: hidden;
}

.valor-editor {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  height: 1.2em;
  padding: 0 2px;
  margin: 0;
  border: 0;
  border-radius: 0;
  outline: 0;
  box-shadow: none;
  background: transparent;
  color: inherit;
  font: 600 20px/1.15 Consolas, "Lucida Console", "Courier New", monospace;
  text-align: center;
  transform: translateY(calc(-50% + 0.05em));
  opacity: 0;
  pointer-events: none;
}

.valor-celda.is-editing .valor-editor {
  opacity: 1;
  pointer-events: auto;
  cursor: text;
}

.valor-editor[aria-invalid="true"] {
  color: #b72e37;
}

.valor-estado {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

