"use strict";

(function () {
  const KEYS = ["varPrincipal", "var1", "var2", "var3"];
  const rows = new Map();
  const queue = [];
  let latestWidget = null;
  let pending = null;

  function own(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
  }

  function raw(entry) {
    return entry && typeof entry === "object" && own(entry, "value")
      ? entry.value : entry;
  }

  function meta(entry) {
    return entry && typeof entry === "object" && !Array.isArray(entry)
      ? entry : {};
  }

  function entryOf(widget, key) {
    const vars = widget.vars && typeof widget.vars === "object" ? widget.vars : {};
    const item = key === "varPrincipal"
      ? (own(vars, key) ? vars[key] : vars.principal)
      : (own(vars, key) ? vars[key] : widget[key]);
    const data = meta(item);
    const value = key === "varPrincipal" && widget.value !== undefined
      ? widget.value : raw(item);
    const hint = key === "varPrincipal"
      ? data.type || data.dataType || data.tipo || widget.dataType || widget.valueType || widget.type
      : data.type || data.dataType || data.tipo;
    return { value: value, meta: data, type: String(hint || "").toLowerCase() };
  }

  function kindOf(entry) {
    if (/bool/.test(entry.type) || typeof entry.value === "boolean") return "bool";
    if (/string|text|char/.test(entry.type)) return "string";
    if (/int|dint|sint|uint|byte|word/.test(entry.type)) return "int";
    if (/real|double|float|decimal|number/.test(entry.type)) return "number";
    if (typeof entry.value === "number") return "number";
    if (typeof entry.value === "string") {
      return /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(entry.value.trim())
        ? "number" : "string";
    }
    return "unknown";
  }

  function display(value) {
    if (value === null || value === undefined) return "-";
    if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
    if (typeof value === "number") return Number.isFinite(value) ? String(value) : "-";
    if (typeof value === "string") return value.trim() || "-";
    return "-";
  }

  function writerFor(key) {
    if (key === "varPrincipal") {
      return typeof window.escribir === "function"
        ? function (value) { window.escribir(value); } : null;
    }
    if (typeof window.escribirVariable === "function") {
      return function (value) { window.escribirVariable(key, value); };
    }
    if (typeof window.escribirVar === "function") {
      return function (value) { window.escribirVar(key, value); };
    }
    if (typeof window.escribir === "function" && window.escribir.length >= 2) {
      return function (value) { window.escribir(value, key); };
    }
    return null;
  }

  function canWrite(row) {
    const widget = latestWidget || {};
    const enabled = widget.escritura !== undefined
      ? widget.escritura : window.WIDGET && window.WIDGET.escritura;
    const m = row.meta || {};
    return enabled === true && m.escritura !== false &&
      m.writable !== false && m.writeable !== false && !!writerFor(row.key);
  }

  function fitText(row) {
    const width = Math.max(1, row.cell.clientWidth - 4);
    const height = Math.max(1, row.cell.clientHeight - 1);
    const span = row.span;
    span.style.maxWidth = "";
    span.style.overflow = "";
    span.style.textOverflow = "";

    const maximum = Math.max(1, Math.min(140, height * 0.78, height * 0.45 + 5));
    const minimum = Math.min(maximum, 11);
    const fits = function (size) {
      span.style.fontSize = size + "px";
      const bounds = span.getBoundingClientRect();
      return bounds.width <= width && bounds.height <= height;
    };
    let chosen = maximum;
    if (!fits(maximum)) {
      if (!fits(minimum)) {
        chosen = minimum;
        span.style.maxWidth = width + "px";
        span.style.overflow = "hidden";
        span.style.textOverflow = "ellipsis";
      } else {
        let low = minimum;
        let high = maximum;
        for (let i = 0; i < 14; i += 1) {
          const middle = (low + high) / 2;
          if (fits(middle)) low = middle;
          else high = middle;
        }
        chosen = Math.floor(low * 100) / 100;
      }
    }
    span.style.fontSize = chosen + "px";
    row.input.style.fontSize = chosen + "px";
  }

  function showValue(row) {
    row.span.textContent = display(row.value);
    fitText(row);
  }

  function finishEdit(row) {
    row.editing = false;
    row.queued = false;
    row.input.readOnly = false;
    row.input.setAttribute("aria-invalid", "false");
    row.cell.classList.remove("is-editing");
    showValue(row);
    row.input.blur();
  }

  function render(widget) {
    latestWidget = widget || window.WIDGET || {};
    if (!rows.size) return;
    for (const key of KEYS) {
      const row = rows.get(key);
      const entry = entryOf(latestWidget, key);
      row.value = entry.value;
      row.meta = entry.meta;
      row.kind = kindOf(entry);
      row.cell.classList.toggle("is-writable", canWrite(row));
      if (row.editing && !canWrite(row) && !row.queued &&
        (!pending || pending.row !== row)) finishEdit(row);
      else if (!row.editing && (!pending || pending.row !== row)) showValue(row);
    }
  }

  function parseValue(text, kind) {
    const trimmed = text.trim();
    if (kind === "string") return { ok: true, value: text };
    if (kind === "bool") {
      if (/^(true|1)$/i.test(trimmed)) return { ok: true, value: true };
      if (/^(false|0)$/i.test(trimmed)) return { ok: true, value: false };
      return { ok: false, message: "Escribe TRUE, FALSE, 1 o 0." };
    }
    if (kind === "unknown") {
      if (/^(true|false)$/i.test(trimmed)) return { ok: true, value: trimmed.toLowerCase() === "true" };
      if (!trimmed) return { ok: true, value: "" };
    }
    const normalized = trimmed.replace(",", ".");
    if (/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(normalized)) {
      const number = Number(normalized);
      if (Number.isFinite(number) && (kind !== "int" || Number.isSafeInteger(number))) {
        return { ok: true, value: number };
      }
    }
    if (kind === "unknown") return { ok: true, value: text };
    return { ok: false, message: kind === "int" ? "Escribe un entero válido." : "Escribe un número válido." };
  }

  function beginEdit(row) {
    if (row.editing || !canWrite(row)) return;
    row.editing = true;
    row.status.textContent = "";
    row.cell.title = "";
    row.input.value = row.value === null || row.value === undefined
      ? "" : typeof row.value === "string" ? row.value : display(row.value);
    row.cell.classList.add("is-editing");
    row.span.textContent = row.input.value || "-";
    fitText(row);
    row.input.focus();
    row.input.select();
  }

  function errorFor(row, message) {
    row.input.setAttribute("aria-invalid", "true");
    row.status.textContent = message;
    row.cell.title = message;
    if (!document.activeElement || document.activeElement === row.input) row.input.focus();
  }

  function submit(row) {
    if (!row.editing || row.queued || (pending && pending.row === row) || !canWrite(row)) return;
    const result = parseValue(row.input.value, row.kind);
    if (!result.ok) { errorFor(row, result.message); return; }
    queue.push({ row: row, value: result.value });
    row.queued = true;
    row.input.readOnly = true;
    row.input.setAttribute("aria-invalid", "false");
    row.status.textContent = "En cola.";
    pump();
  }

  function pump() {
    if (pending) return;
    while (queue.length) {
      const item = queue.shift();
      const row = item.row;
      row.queued = false;
      const writer = writerFor(row.key);
      if (!row.editing || !canWrite(row) || !writer) {
        row.input.readOnly = false;
        if (row.editing) errorFor(row, "No se puede escribir este tag.");
        continue;
      }
      pending = item;
      row.status.textContent = "Enviando valor.";
      try { writer(item.value); }
      catch (error) {
        pending = null;
        row.input.readOnly = false;
        errorFor(row, error && error.message ? error.message : "No se pudo escribir el valor.");
        continue;
      }
      return;
    }
  }

  window.onWidgetUpdate = render;
  window.onWidgetEscrito = function (result) {
    if (!pending) return;
    const alias = result && (result.alias || result.variable);
    if (alias && alias !== pending.row.key &&
      !(alias === "principal" && pending.row.key === "varPrincipal")) return;
    const submitted = pending;
    pending = null;
    const row = submitted.row;
    if (!result || result.ok !== true || result.error) {
      row.input.readOnly = false;
      errorFor(row, String(result && result.error || "El PLC rechazó la escritura."));
    } else {
      row.value = submitted.value;
      row.status.textContent = "Valor enviado.";
      finishEdit(row);
    }
    pump();
  };

  function initialize() {
    const root = document.querySelector(".cuatro-valores");
    if (!root) return;
    for (const cell of root.querySelectorAll(".valor-celda")) {
      const row = {
        key: cell.dataset.variable,
        cell: cell,
        span: cell.querySelector(".valor-contenido"),
        input: cell.querySelector(".valor-editor"),
        status: cell.querySelector(".valor-estado"),
        meta: {},
        kind: "unknown",
        value: undefined,
        editing: false,
        queued: false
      };
      rows.set(row.key, row);
      cell.addEventListener("click", function () { beginEdit(row); });
      row.input.addEventListener("input", function () {
        row.span.textContent = row.input.value || "-";
        row.input.setAttribute("aria-invalid", "false");
        row.status.textContent = "";
        row.cell.title = "";
        fitText(row);
      });
      row.input.addEventListener("keydown", function (event) {
        if (event.isComposing) return;
        if (event.key === "Enter") { event.preventDefault(); submit(row); }
        if (event.key === "Escape" && (!pending || pending.row !== row)) {
          event.preventDefault();
          for (let i = queue.length - 1; i >= 0; i -= 1) {
            if (queue[i].row === row) queue.splice(i, 1);
          }
          finishEdit(row);
        }
      });
      row.input.addEventListener("blur", function () {
        if (row.editing && !row.queued && (!pending || pending.row !== row)) finishEdit(row);
      });
    }
    render(latestWidget || window.WIDGET || {});
    if (typeof ResizeObserver !== "undefined") {
      new ResizeObserver(function () { rows.forEach(fitText); }).observe(root);
    } else window.addEventListener("resize", function () { rows.forEach(fitText); });
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () { rows.forEach(fitText); });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, { once: true });
  } else initialize();
})();
